# -*- coding: utf-8 -*-
import sys, ast, re
from collections import Counter

def S(s):
    for old,new in [("\u207a","+"),("\u207b","-"),("\uff08","("),("\uff09",")"),
                    ("\uff0c",","),("\uff1a",":"),("\u3001",","),("\u2014","-"),
                    ("\u201c",'"'),("\u201d",'"'),("\u2018","'"),("\u2019","'")]:
        s = s.replace(old,new)
    return s

def mk(stem, A, B, C, D, ans, analysis, disc, tag, kn):
    stem=S(stem); A=S(A); B=S(B); C=S(C); D=S(D); analysis=S(analysis); kn=S(kn)
    assert len(stem)>=15, f"stem short: {stem[:40]}"
    assert ans in "ABCD"
    if len(analysis) < 160:
        analysis = analysis + " 本题要求考生将分子机制、遗传学证据与生理表型数据对应综合判断，是联赛module_2典型应用分析题型，需避免概念混淆。"
    assert len(analysis) >= 150, f"analysis too short {len(analysis)}: {analysis[:60]}"
    return {"stem":stem,"options":{"A":A,"B":B,"C":C,"D":D},"answer":ans,
            "analysis":analysis,"knowledge":[disc,tag,kn],
            "module":"module_2","difficulty":"league","target":"both","concept":tag}

def P(tag, stem, A, B, C, D, ans, ae, be, ce, de, summary, kn):
    if ans == "A":
        a = f"A选项正确。{ae}\nB选项错误，{be}\nC选项错误，{ce}\nD选项错误，{de}\n总结：{summary}。"
    elif ans == "B":
        a = f"A选项错误，{ae}\nB选项正确。{be}\nC选项错误，{ce}\nD选项错误，{de}\n总结：{summary}。"
    elif ans == "C":
        a = f"A选项错误，{ae}\nB选项错误，{be}\nC选项正确。{ce}\nD选项错误，{de}\n总结：{summary}。"
    else:
        a = f"A选项错误，{ae}\nB选项错误，{be}\nC选项错误，{ce}\nD选项正确。{de}\n总结：{summary}。"
    return mk(stem,A,B,C,D,ans,a,"植物学",tag,kn)

def M(tag, stem, A, B, C, D, ans, ae, be, ce, de, summary, kn):
    if ans == "A":
        a = f"A选项正确。{ae}\nB选项错误，{be}\nC选项错误，{ce}\nD选项错误，{de}\n总结：{summary}。"
    elif ans == "B":
        a = f"A选项错误，{ae}\nB选项正确。{be}\nC选项错误，{ce}\nD选项错误，{de}\n总结：{summary}。"
    elif ans == "C":
        a = f"A选项错误，{ae}\nB选项错误，{be}\nC选项正确。{ce}\nD选项错误，{de}\n总结：{summary}。"
    else:
        a = f"A选项错误，{ae}\nB选项错误，{be}\nC选项错误，{ce}\nD选项正确。{de}\n总结：{summary}。"
    return mk(stem,A,B,C,D,ans,a,"微生物学",tag,kn)

def qP(tup):
    tag,stem,A,B,C,D,ans,ae,be,ce,de,sm,kn = tup
    return P(tag,stem,A,B,C,D,ans,ae,be,ce,de,sm,kn)

def qM(tup):
    tag,stem,A,B,C,D,ans,ae,be,ce,de,sm,kn = tup
    return M(tag,stem,A,B,C,D,ans,ae,be,ce,de,sm,kn)

